package com.bananalab.lite;
import android.content.*;import java.util.regex.*;
final class SceneTurns{
 static BananaEngine.Result handle(Context c,String input)throws Exception{Matcher m=Pattern.compile("^alterna dialogo (\\d{1,2}) turnos$").matcher(ChatLanguage.normalize(input));if(!m.matches())return null;int count=Integer.parseInt(m.group(1));if(count<1||count>32)return MobileCore.say(c,"Entre1 y32 turnos.","escena");SceneDraft base=MobileCore.scene(c);if(base==null||base.cast.isEmpty())return MobileCore.say(c,"Primero creá los personajes.","escena");SceneDraft d=base.copy();d.actions.clear();d.actors.clear();d.slots.clear();d.targets.clear();d.recipients.clear();d.dialogue.clear();for(int i=0;i<count;i++){int actor=JavaAlgorithm.kind().equals("turn")?Integer.parseInt(JavaAlgorithm.process(i+","+d.cast.size())):i%d.cast.size();if(actor<0||actor>=d.cast.size())return MobileCore.say(c,"El algoritmo eligió un personaje inválido; conservé la escena.","escena");SceneDirector.step(d,d.cast.get(actor),"habla",i,"","");}SceneTiming.fit(d);SceneConsistency.require(d);CreatorSession state=CreatorMemory.load(c);CreatorSession.Result result=state.update(d,state.pending!=null,"Preparé "+count+" turnos conservando los personajes.",false);CreatorMemory.save(c,state,result.commit);BananaEngine.Result out=MobileCore.say(c,result.text,"escena");out.changed=result.commit!=null;return out;}
}
